import json, math

def verify(answer):
    """Mechanical GRPO verifier for batch-002 scenario 1 (Conservation Mirage).
    Recomputes the mass-conserving reweighting and the gain sums, checks the
    singularity verdict, the channel-dependent expert routing, and the
    reliability veto on the TD-carried playoff spike."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    # Layer 1: conservation arithmetic (578457115b76903d:p2, p.4)
    n_p, n_n, alpha_p = 3, 14, 1.25
    alpha_n_ref = (n_p + n_n - alpha_p * n_p) / n_n  # 13.25/14
    a = answer.get("alpha_n")
    if not num(a) or abs(a - alpha_n_ref) > 1e-6:
        return False
    if answer.get("mass_conservation_holds") is not True:
        return False
    if abs(alpha_p * n_p + alpha_n_ref * n_n - (n_p + n_n)) > 1e-9:
        return False  # sanity: the identity itself
    g_unw_ref = 14 * 0.5 + 3 * 8.0          # 31.0
    g_w_ref = alpha_n_ref * 14 * 0.5 + alpha_p * 3 * 8.0  # 36.625
    gu, gw = answer.get("g_a_unweighted"), answer.get("g_a_weighted")
    if not num(gu) or abs(gu - g_unw_ref) > 1e-6:
        return False
    if not num(gw) or abs(gw - g_w_ref) > 1e-6:
        return False
    # Flat-profile invariance and the n_n = 0 singularity
    if answer.get("flat_asset_gain_invariant_under_reweighting") is not True:
        return False
    if answer.get("playoffs_only_reweighting_status") != "singular_undefined":
        return False
    # Acceptance kernel: mixed-weight fairness channel
    if answer.get("fairness_channel_mixes_weighted_and_unweighted") is not True:
        return False
    # Psychology layer: channel-dependent expert routing (cea9c306f975be55:p6,p4)
    if answer.get("qb_expert_correction") != "strip":
        return False
    if answer.get("rb_expert_correction") != "keep":
        return False
    # Measurement layer: TD channel band + stability veto
    if answer.get("playoff_spike_channel_r2_band") != "0.20-0.30":
        return False
    if answer.get("spike_is_stable_skill_signal") is not False:
        return False
    if answer.get("trade_decision") != "veto_reweight_and_reprice":
        return False
    return True

import json, math

def verify(answer):
    """Mechanical GRPO verifier for batch-002 scenario 2 (Reversed Cadence).
    Recomputes the timing-order sign, the after-effect window, the CSP rank
    condition, Eq. 1's r^2, and the Elo residual update; rejects any answer
    that installs the cadence or trusts population-average transfer."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    # (1) STDP timing-order sign from the telemetry (090cfc0da55b02cd:p5, p.3)
    pre = [1.82, 1.91, 1.77]   # press trigger
    post = [1.65, 1.70, 1.61]  # coverage shift
    if all(b < a for a, b in zip(pre, post)):
        sign_ref = "depression"  # post-before-pre -> long-lasting inhibition
    elif all(a < b for a, b in zip(pre, post)):
        sign_ref = "potentiation"
    else:
        return False  # inconsistent order: scenario would be ill-posed
    if answer.get("timing_order_sign") != sign_ref:
        return False
    # (2) individual-reversal / significance veto
    if answer.get("population_gain_transfers_to_individual") is not False:
        return False
    if answer.get("tacs_vs_sham_significant") is not False:
        return False
    # (3) after-effect window: 09:40 + ~30 min -> 10:10
    if answer.get("next_session_inside_tacs_aftereffect") is not True:
        return False
    if answer.get("earliest_unconfounded_session") != "10:10":
        return False
    # (4) CSP rank condition N < T (090cfc0da55b02cd:p2, p.6)
    N, T = 44, 40
    if N >= T:
        if answer.get("csp_admissible") is not False:
            return False
        if answer.get("csp_failure_mode") != "rank_deficient_whitening_singular":
            return False
    # (5) Eq. 1 recomputation + first-moment blindness
    N1 = N2 = 30
    r2_ref = (math.sqrt(N1 * N2 / (N1 + N2)) * (9.0 - 8.0) / 4.0) ** 2  # 0.9375
    r2 = answer.get("r2_band_value")
    if not num(r2) or abs(r2 - r2_ref) > 1e-6:
        return False
    if answer.get("timing_only_phase_visible_to_r2_selector") is not False:
        return False
    # (6) calibration veto (95719becd340bcea:p6, pp.19-20)
    if answer.get("nb_accuracy_certifies_probability") is not False:
        return False
    if answer.get("nb_distance_angle_independent") is not False:
        return False
    # (7) Elo residual update at printed optimized eta (95719becd340bcea:p1, p.41)
    R_ref = 1.50 + 0.15 * (2.40 - 1.60)  # 1.62
    R = answer.get("elo_updated_rating")
    if not num(R) or abs(R - R_ref) > 1e-6:
        return False
    if answer.get("eta_0_9_admissible") is not False:
        return False
    if answer.get("install_cadence_as_proposed") is not False:
        return False
    return True

import json, math

def verify(answer):
    """Mechanical GRPO verifier for batch-002 scenario 3 (Matched-Seed Mirage).
    Recomputes both confidence intervals from the printed formulas, checks the
    covariance verdict, the pressure-gated payoff, and the fusion/latency/
    doctrine vetoes; rejects promotion of T1 on the mirrored evidence."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    n, w1, w2 = 1000, 520, 470
    p1, p2 = w1 / n, w2 / n
    d = p1 - p2
    if not num(answer.get("p_hat_T1")) or abs(answer["p_hat_T1"] - p1) > 1e-9:
        return False
    if not num(answer.get("p_hat_T2")) or abs(answer["p_hat_T2"] - p2) > 1e-9:
        return False
    # (1) same-survey multinomial vs independent-samples intervals
    if answer.get("required_variance") != "same_survey_multinomial":
        return False
    se_multi = math.sqrt((p1 + p2 - d * d) / n)
    se_ind = math.sqrt((p1 * (1 - p1) + p2 * (1 - p2)) / n)
    ci_m = [d - 1.96 * se_multi, d + 1.96 * se_multi]
    ci_i = [d - 1.96 * se_ind, d + 1.96 * se_ind]
    for key, ref in (("ci95_multinomial", ci_m), ("ci95_independent_samples", ci_i)):
        got = answer.get(key)
        if not isinstance(got, list) or len(got) != 2:
            return False
        if not all(num(x) for x in got):
            return False
        if abs(got[0] - ref[0]) > 5e-4 or abs(got[1] - ref[1]) > 5e-4:
            return False
    m_contains = ci_m[0] <= 0.0 <= ci_m[1]
    i_contains = ci_i[0] <= 0.0 <= ci_i[1]
    if answer.get("multinomial_ci_contains_zero") is not m_contains:
        return False
    if answer.get("independent_ci_contains_zero") is not i_contains:
        return False
    if not m_contains or i_contains:
        return False  # sanity: the mirage structure must hold
    if answer.get("superiority_verdict") != "no_conclusion":
        return False
    # (3) additive vs pressure-gated QB-OL payoff (62af700cfd3180fa:p3,p4, p.7)
    u_add = 9 * 0.06 + 4 * 0.55          # 2.74
    u_gate = 9 * 0.06 * 0.38 + 4 * 0.55  # 2.4052
    ua, ug = answer.get("u_qb_additive"), answer.get("u_qb_pressure_gated")
    if not num(ua) or abs(ua - u_add) > 1e-6:
        return False
    if not num(ug) or abs(ug - u_gate) > 1e-6:
        return False
    if answer.get("rho_downweights_rare_td_pass") is not True:
        return False
    # (4) fusion: simplex admissible, effective N collapsed
    weights = [0.5, 0.3, 0.2]
    simplex = all(w >= 0 for w in weights) and abs(sum(weights) - 1.0) < 1e-9
    if answer.get("fusion_weights_on_simplex") is not simplex:
        return False
    if answer.get("crowd_effective_n_collapsed") is not True:
        return False
    # (5) latency veto: 7-day charting is validation-only
    if answer.get("charted_pressure_live_call_admissible") is not False:
        return False
    # (6) doctrine + count-process vetoes
    if answer.get("total_line_admissible") is not False:
        return False
    if answer.get("poisson_independence_holds_in_game") is not False:
        return False
    # (2) search veto and final decision
    if answer.get("searched_significance_admissible") is not False:
        return False
    if answer.get("promote_T1_on_this_evidence") is not False:
        return False
    return True
